import{j as i}from"./motion-Sdvamqzz.js";import{A as u,a as h,b as p,c as l}from"./accordion-D2iK8-4R.js";import{E as y,u as f}from"./index-CZ1u9xY-.js";function F({items:n,className:e,defaultOpen:a}){return n.length===0?null:i.jsx(u,{type:"single",collapsible:!0,defaultValue:a,className:y("space-y-3",e),children:n.map(o=>i.jsxs(h,{value:o.id,children:[i.jsx(p,{children:o.question}),i.jsx(l,{children:o.answer})]},o.id))})}function t(n,e){return n[e]}function r(){const{locale:n}=f();return n==="ar-EG"?"ar":"en"}const c=[{id:"pf-01",category:{ar:"عام",en:"General"},question:{ar:"إيه هي منصة أستاذ بالظبط؟",en:"What exactly is USTAZ?"},answer:{ar:"أستاذ منصة مصرية بتدّي كل مدرّس موقع شخصي احترافي جوه المنصة: بروفايل بيعرض خبرتك وطريقتك، مجموعاتك ومواعيدها، كورساتك، تقييمات طلابك، وطريقة تواصل مباشرة على واتساب. والطالب بيقدر يدوّر ويقارن ويشترك من مكان واحد.",en:"USTAZ is an Egyptian platform that gives every teacher a professional presence: a profile showing your experience and approach, your groups and their times, your courses, your students’ reviews, and a direct WhatsApp channel. Students search, compare, and enrol from one place."}},{id:"pf-02",category:{ar:"عام",en:"General"},question:{ar:"المنصة دي بديل للسنتر؟",en:"Is this a replacement for a centre?"},answer:{ar:"لأ خالص. أستاذ مش بتاخد مكان السنتر ولا بتنافسه — دي الواجهة الرقمية لشغلك سواء كنت بتدرّس في سنتر، في بيتك، أو أونلاين. إنت اللي بتحدد مواعيدك وأسعارك وطريقة استلام الفلوس.",en:"Not at all. USTAZ does not replace or compete with your centre — it is the digital front for your teaching, whether that happens in a centre, at home, or online. You set your times, your prices, and how you get paid."}},{id:"pf-03",category:{ar:"للمدرّسين",en:"For teachers"},question:{ar:"إزاي أبدأ كمدرّس على المنصة؟",en:"How do I start as a teacher?"},answer:{ar:"تسجّل حساب مدرّس، تملا بيانات بروفايلك (المادة، المراحل، الخبرة، طريقتك)، تضيف مجموعاتك بمواعيدها وأسعارها، وتنشر البروفايل. العملية كلها بتاخد أقل من نص ساعة.",en:"Create a teacher account, fill in your profile (subject, stages, experience, your approach), add your groups with their times and prices, and publish. The whole thing takes under half an hour."}},{id:"pf-04",category:{ar:"للمدرّسين",en:"For teachers"},question:{ar:"المنصة بتاخد نسبة من اشتراكات الطلبة؟",en:"Do you take a cut of what students pay?"},answer:{ar:"لأ. الباقات اشتراك شهري ثابت للمدرّس، والفلوس بينك وبين الطالب مباشرة. إحنا مش وسيط في الدفع.",en:"No. Plans are a flat monthly subscription for the teacher, and the money moves directly between you and your student. We are not a payment intermediary."}},{id:"pf-05",category:{ar:"للمدرّسين",en:"For teachers"},question:{ar:"أقدر أغيّر أسعاري أو مواعيدي في أي وقت؟",en:"Can I change my prices or times whenever I want?"},answer:{ar:"طبعًا. كل حاجة في لوحة التحكم بتتعدّل لحظيًا، والتغيير بيظهر على بروفايلك فورًا.",en:"Of course. Everything in the console is editable, and the change shows on your profile immediately."}},{id:"pf-06",category:{ar:"للطلاب",en:"For students"},question:{ar:"إزاي أختار المدرّس المناسب؟",en:"How do I choose the right teacher?"},answer:{ar:"تقدر تفلتر حسب المادة والصف والمحافظة وطريقة الشرح (أونلاين/حضوري) والتقييم. وكل بروفايل فيه طريقة المدرّس وتقييمات حقيقية من طلابه وجدوله الأسبوعي.",en:"Filter by subject, grade, governorate, teaching mode (online or in person), and rating. Every profile shows the teacher’s approach, real reviews from their students, and their weekly schedule."}},{id:"pf-07",category:{ar:"للطلاب",en:"For students"},question:{ar:"الاشتراك بيتم إزاي؟",en:"How does enrolling work?"},answer:{ar:"بتملا فورم الاشتراك في المجموعة، وبعدها بتكمّل مع المدرّس مباشرة على واتساب لتأكيد المكان وطريقة الدفع اللي بتناسبكم.",en:"You submit the group’s enrolment form, then continue with the teacher directly on WhatsApp to confirm your place and agree how to pay."}},{id:"pf-08",category:{ar:"للطلاب",en:"For students"},question:{ar:"في حصص تجريبية؟",en:"Are there trial lessons?"},answer:{ar:"أغلب المدرّسين بيوفّروا حصة تجريبية مجانية، وده مكتوب في صفحة كل مجموعة.",en:"Most teachers offer a free trial lesson, and each group page says whether it does."}},{id:"pf-09",category:{ar:"الدفع",en:"Payments"},question:{ar:"إيه طرق الدفع المتاحة؟",en:"What payment methods are available?"},answer:{ar:"الدفع بيتم مباشرة مع المدرّس بالطريقة اللي تتفقوا عليها — كاش، محفظة موبايل، أو تحويل بنكي. المنصة مش بتتدخّل في الدفع.",en:"You pay the teacher directly, however you both agree — cash, mobile wallet, or bank transfer. The platform stays out of the payment."}},{id:"pf-10",category:{ar:"الدفع",en:"Payments"},question:{ar:"أكواد الخصم بتشتغل إزاي؟",en:"How do discount codes work?"},answer:{ar:"بتكتب الكود في فورم الاشتراك وبيتحسب الخصم فورًا قدامك قبل ما تكمّل. وبيظهر السعر الأصلي والسعر بعد الخصم بوضوح.",en:"Enter the code on the enrolment form and the discount is applied in front of you before you continue, with the original and final prices both shown."}},{id:"pf-11",category:{ar:"تقني",en:"Technical"},question:{ar:"محتاج أنزّل تطبيق؟",en:"Do I need to install an app?"},answer:{ar:"لأ، المنصة بتشتغل من المتصفح على الموبايل والكمبيوتر، وتقدر تضيفها للشاشة الرئيسية زي أي تطبيق.",en:"No. It runs in the browser on phones and computers, and you can add it to your home screen like any app."}},{id:"pf-12",category:{ar:"تقني",en:"Technical"},question:{ar:"بياناتي آمنة؟",en:"Is my data safe?"},answer:{ar:"بنجمع أقل قدر ممكن من البيانات، ورقم تليفونك مبيظهرش لحد غير المدرّس اللي أنت بتتواصل معاه.",en:"We collect as little as possible, and your phone number is never shown to anyone but the teacher you chose to contact."}}],m=[{id:"pr-01",category:{ar:"الباقات",en:"Plans"},question:{ar:"أقدر أغيّر الباقة في أي وقت؟",en:"Can I change plan at any time?"},answer:{ar:"أيوه، تقدر ترقّي أو تنزّل الباقة في أي وقت، والفرق بيتحسب بالتناسب مع الأيام المتبقية.",en:"Yes — upgrade or downgrade whenever you like, and the difference is prorated against the days remaining."}},{id:"pr-02",category:{ar:"الباقات",en:"Plans"},question:{ar:"في التزام بعقد سنوي؟",en:"Am I locked into an annual contract?"},answer:{ar:"لأ. كل الباقات شهرية وتقدر توقف أي وقت. الاشتراك السنوي اختياري وبيوفّر أكتر.",en:"No. Every plan is monthly and you can stop any time. Paying yearly is optional and costs less."}},{id:"pr-03",category:{ar:"الباقات",en:"Plans"},question:{ar:"إيه اللي بيحصل لبروفايلي لو وقفت الاشتراك؟",en:"What happens to my profile if I stop paying?"},answer:{ar:"البروفايل بيرجع للباقة المجانية وبيفضل شغّال، بس المميزات المدفوعة بتتوقف.",en:"Your profile drops back to the free plan and stays online; the paid features simply stop."}}];function s(n,e){return n.map(a=>({id:a.id,question:t(a.question,e),answer:t(a.answer,e),category:t(a.category,e)}))}function I(){return s(c,r())}const g=["pf-01","pf-03","pf-04","pf-06","pf-07","pf-10"];function W(){const n=r();return s(c.filter(e=>g.includes(e.id)),n)}function E(){const n=r();return s(c.filter(e=>["pf-02","pf-04","pf-11","pf-12"].includes(e.id)),n)}function S(){return s(m,r())}const w=[{id:"ht-1",number:{ar:"٠١",en:"01"},audience:"teacher",title:{ar:"اعمل بروفايلك",en:"Build your profile"},description:{ar:"سجّل، واملا مادتك ومراحلك وخبرتك وطريقتك في الشرح.",en:"Sign up and fill in your subject, stages, experience, and how you teach."}},{id:"ht-2",number:{ar:"٠٢",en:"02"},audience:"teacher",title:{ar:"ضيف مجموعاتك",en:"Add your groups"},description:{ar:"حدّد المواعيد والسعر وعدد الأماكن، وسيب الباقي على المنصة.",en:"Set the times, the price, and the seats — the platform handles the rest."}},{id:"ht-3",number:{ar:"٠٣",en:"03"},audience:"teacher",title:{ar:"استقبل طلابك",en:"Take enrolments"},description:{ar:"الطلاب بيشوفوا بروفايلك ويشتركوا، والتواصل بيكمّل على واتساب.",en:"Students find your profile and enrol, then the conversation continues on WhatsApp."}},{id:"ht-4",number:{ar:"٠٤",en:"04"},audience:"teacher",title:{ar:"تابع شغلك",en:"Run your teaching"},description:{ar:"حضور وواجبات وامتحانات ودرجات ومدفوعات، كلها من لوحة واحدة.",en:"Attendance, homework, exams, grades, and payments — all from one console."}},{id:"hs-1",number:{ar:"٠١",en:"01"},audience:"student",title:{ar:"دوّر وقارن",en:"Search and compare"},description:{ar:"فلتر حسب المادة والصف والمحافظة وطريقة الشرح، وقارن بالتقييمات.",en:"Filter by subject, grade, governorate, and teaching mode, then compare by rating."}},{id:"hs-2",number:{ar:"٠٢",en:"02"},audience:"student",title:{ar:"اقرا البروفايل",en:"Read the profile"},description:{ar:"اعرف خبرة المدرّس وطريقته وشوف آراء طلابه الحاليين وجدوله.",en:"See the teacher’s experience and approach, their students’ reviews, and their schedule."}},{id:"hs-3",number:{ar:"٠٣",en:"03"},audience:"student",title:{ar:"اشترك في مجموعة",en:"Join a group"},description:{ar:"اختار المجموعة المناسبة لمواعيدك، طبّق كود الخصم، وكمّل على واتساب.",en:"Pick the group that fits your week, apply a discount code, and continue on WhatsApp."}},{id:"hs-4",number:{ar:"٠٤",en:"04"},audience:"student",title:{ar:"تابع جدولك",en:"Follow your schedule"},description:{ar:"كل حصصك من كل المدرّسين في جدول واحد، مع تنبيه قبل كل حصة.",en:"Every class from every teacher in one schedule, with a reminder before each one."}}];function d(n){const e=r();return w.filter(a=>a.audience===n).map(a=>({id:a.id,number:t(a.number,e),audience:a.audience,title:t(a.title,e),description:t(a.description,e)}))}function x(){return d("teacher")}function C(){return d("student")}const b=[{id:"av-1",title:{ar:"المدرّس هو المنتج",en:"The teacher is the product"},description:{ar:"إحنا مش بنبيع كورسات — إحنا بنبني أدوات تخلي المدرّس يبان بأحسن صورة. كل قرار تصميم بنسأل قبله: ده بيخدم المدرّس ولا بيستغلّه؟",en:"We do not sell courses — we build tools that show a teacher at their best. Before every design decision we ask whether it serves the teacher or exploits them."}},{id:"av-2",title:{ar:"شفافية في الأسعار",en:"Transparent pricing"},description:{ar:"السعر الأصلي والخصم والسعر النهائي ظاهرين دايمًا. مفيش رسوم مخفية ومفيش نسبة بناخدها من اشتراك الطالب.",en:"The original price, the discount, and the final price are always visible. No hidden fees, and no cut of what a student pays."}},{id:"av-3",title:{ar:"واتساب مش بديل",en:"WhatsApp, not a replacement"},description:{ar:"التواصل الحقيقي في مصر بيحصل على واتساب. فبدل ما نجبر الناس تستخدم شات تاني، بنوصّلهم لواتساب برسالة جاهزة فيها كل التفاصيل.",en:"Real conversation in Egypt happens on WhatsApp. Rather than forcing another chat app on people, we hand them a ready-written message with the details already in it."}},{id:"av-4",title:{ar:"يشتغل على أي موبايل",en:"Works on any phone"},description:{ar:"أغلب طلابنا بيفتحوا المنصة من موبايل متوسط وشبكة مش أحسن حاجة. فالسرعة والبساطة عندنا مش رفاهية.",en:"Most of our students open the platform on a mid-range phone and an imperfect connection, so speed and simplicity are not luxuries here."}}];function P(){const n=r();return b.map(e=>({id:e.id,title:t(e.title,n),description:t(e.description,n)}))}const v=[{id:"at-1",year:"2024",title:{ar:"الفكرة",en:"The idea"},description:{ar:"بدأنا من ملاحظة بسيطة: أحسن المدرّسين في مصر مالهمش أي وجود رقمي محترم غير جروب واتساب وبوست فيسبوك.",en:"It started with a simple observation: Egypt’s best teachers had no real digital presence beyond a WhatsApp group and a Facebook post."}},{id:"at-2",year:"2024",title:{ar:"أول المدرّسين",en:"The first teachers"},description:{ar:"اشتغلنا مع مجموعة مدرّسين من محافظات مختلفة وبنينا المنتج على ملاحظاتهم مباشرة.",en:"We worked with a group of teachers across several governorates and built the product directly on their feedback."}},{id:"at-3",year:"2025",title:{ar:"لوحة التحكم",en:"The console"},description:{ar:"أطلقنا لوحة تحكم كاملة للمدرّس: مجموعات، طلاب، حضور، مدفوعات، وتحليلات.",en:"We launched the full teacher console: groups, students, attendance, payments, and analytics."}},{id:"at-4",year:"2026",title:{ar:"أستاذ النهاردة",en:"USTAZ today"},description:{ar:"منصة كاملة للمدرّس والطالب وولي الأمر، وكل مدرّس عنده صفحته الخاصة.",en:"A complete platform for teachers, students, and parents — and every teacher has a page of their own."}}];function N(){const n=r();return v.map(e=>({id:e.id,year:e.year,title:t(e.title,n),description:t(e.description,n)}))}const A=[{id:"cc-1",title:{ar:"واتساب",en:"WhatsApp"},description:{ar:"أسرع طريقة — بنرد خلال ساعة في أيام العمل.",en:"The fastest route — we reply within an hour on working days."},value:{ar:"0100 000 0000",en:"0100 000 0000"},kind:"whatsapp"},{id:"cc-2",title:{ar:"البريد الإلكتروني",en:"Email"},description:{ar:"للاستفسارات التفصيلية والشراكات.",en:"For detailed questions and partnerships."},value:{ar:"hello@ustaz.eg",en:"hello@ustaz.eg"},kind:"email"},{id:"cc-3",title:{ar:"المقر",en:"Office"},description:{ar:"زيارة بموعد مسبق.",en:"Visits by appointment."},value:{ar:"القاهرة الجديدة، القاهرة",en:"New Cairo, Cairo"},kind:"address"}];function j(){const n=r();return A.map(e=>({id:e.id,title:t(e.title,n),description:t(e.description,n),value:t(e.value,n),kind:e.kind}))}export{F,N as a,x as b,C as c,W as d,j as e,E as f,S as g,I as h,P as u};
